insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  '991d6ee9-8796-4a59-bd1d-bf6f0e657ff8',
  'passage.u01.section.1-10-track-101',
  'e321a5a0-9cb2-4cbd-acfe-0bc1ac533ce1',
  '인사하기',
  '인사하기',
  '왕 루: 안녕하십니까? 처음 뵙겠습니다.
자르갈: 네, 안녕하십니까? 저는 자르갈입니다. 처음 뵙겠습니다. 이름이 무엇입니까?
왕 루: 제 이름은 왕루입니다. 자르갈 씨는 어느 나라 사람입니까?
자르갈: 저는 몽골 사람입니다. 왕루 씨는 어디에서 왔습니까?
왕 루: 저는 중국에서 왔습니다. 만나서 반갑습니다.
자르갈: 만나서 반갑습니다.',
  null,
  '{}'::jsonb,
  'draft',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  'cb054ae0-cf0a-4548-88bd-a3fd96d4ea35',
  'passage.u01.section.2-102-track-102',
  'e321a5a0-9cb2-4cbd-acfe-0bc1ac533ce1',
  '자기소개하기',
  '자기소개하기',
  '아멜리: 안녕하세요? 저는 아멜리입니다. 이름이 무엇입니까?
파하드: 제 이름은 파하드입니다. 사우디에서 왔습니다. 아멜리 씨도 사우디 사람입니까?
아멜리: 아니요, 저는 사우디 사람이 아닙니다. 프랑스 사람입니다. 파하드 씨는 선생님입니까?
파하드: 아니요, 저는 선생님이 아닙니다. 학생입니다.
아멜리: 저도 학생입니다. 만나서 반갑습니다.
파하드: 만나서 반갑습니다.',
  null,
  '{}'::jsonb,
  'draft',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  '0a6d8827-7c4b-4994-a4c1-e84a0ed50791',
  'passage.u01.section.s003',
  'e321a5a0-9cb2-4cbd-acfe-0bc1ac533ce1',
  '자기소개하기',
  '자기소개하기',
  '왕루: 안녕하십니까?
흐엉: 네, 안녕하세요? 제 이름은 (흐엉)입니다. 이름이 무엇입니까?
왕루: 저는 (왕루)입니다. (흐엉) 씨는 어느 나라 사람입니까?
흐엉: 저는 (베트남) 사람입니다. 왕루 씨는 (몽골) 사람입니까?
왕루: 아니요, 저는 (몽골) 사람이 아닙니다. (중국)에서 왔습니다.
흐엉: (왕루) 씨는 (선생님)입니까?
왕루: 아니요, 저는 (선생님)이/가 아닙니다. (학생)입니다. (흐엉) 씨도 (학생)입니까?
흐엉: 네, 저도 (학생)입니다. 만나서 반갑습니다.
왕루: 만나서 반갑습니다.',
  null,
  '{}'::jsonb,
  'draft',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  'c6a6d4f2-14e2-47e1-8be4-cd19a135416c',
  'passage.u01.section.s004',
  'e321a5a0-9cb2-4cbd-acfe-0bc1ac533ce1',
  '자기소개에 대한 글을 읽고 말하기',
  '자기소개에 대한 글을 읽고 말하기',
  '안녕하십니까? 만나서 반갑습니다. 제 이름은 왕루입니다. 저는 중국에서 왔습니다. 저는 학생입니다.
아멜리 씨는 제 친구입니다. 아멜리 씨는 중국 사람이 아닙니다. 프랑스에서 왔습니다. 자르갈 씨도 제 친구입니다. 자르갈 씨는 몽골 사람입니다. 자르갈 씨도 학생입니다.
모두 우리 반 친구입니다.',
  null,
  '{}'::jsonb,
  'published',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  'ac0cf754-4784-4a61-81f0-9544a7ac6cb1',
  'passage.u01.section.s005',
  'e321a5a0-9cb2-4cbd-acfe-0bc1ac533ce1',
  '한국의 인사 방법',
  '한국의 인사 방법',
  '친구를 만납니다. “안녕하세요?” 눈을 보고 인사합니다.
선생님을 만납니다. “안녕하십니까?” 머리를 숙이고 인사합니다.',
  null,
  '{}'::jsonb,
  'draft',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  '766a1e50-0592-45bb-9f00-a7b3dfd186cc',
  'passage.u02.section.1-track-105',
  '706d624f-aefd-42e9-a146-d7b88ae10f4d',
  '교실 물건을 말하기',
  '교실 물건을 말하기',
  '왕 루: 자르갈 씨, 이것이 무엇입니까?
자르갈: 그것은 책상입니다.
왕 루: 저것이 무엇입니까?
자르갈: 저것은 시계입니다.
왕 루: 그 가방이 자르갈 씨의 가방입니까?
자르갈: 아니요, 이 가방은 제 것이 아닙니다. 아멜리 씨의 가방입니다.
왕 루: 여기가 누구의 교실입니까?
자르갈: 여기는 우리의 교실입니다.',
  null,
  '{}'::jsonb,
  'draft',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  'dcdef632-5bf7-4dd2-bc3c-c350bf7e0a02',
  'passage.u02.section.2-track-106',
  '706d624f-aefd-42e9-a146-d7b88ae10f4d',
  '학교 시설물의 위치를 설명하기',
  '학교 시설물의 위치를 설명하기',
  '아멜리: 파하드 씨, 안녕하세요?
파하드: 네, 아멜리 씨, 안녕하세요? 학교에 은행이 있습니까?
아멜리: 예, 학교에 은행이 있습니다.
파하드: 은행이 어디에 있습니까?
아멜리: 이 건물 옆에 있습니다.
파하드: 도서관은 어디에 있습니까?
아멜리: 도서관은 운동장 앞에 있습니다.
파하드: 아멜리 씨, 고맙습니다.',
  null,
  '{}'::jsonb,
  'draft',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  '95800f36-6045-464c-b849-2b6147f8e5d8',
  'passage.u02.section.35',
  '706d624f-aefd-42e9-a146-d7b88ae10f4d',
  '위치를 묻고 답하기',
  '위치를 묻고 답하기',
  '로빈: (제냐) 씨, 안녕하세요?
제냐: (로빈) 씨, 안녕하세요?
로빈: 학교에 (도서관)이/가 있습니까?
제냐: 네, (도서관)이/가 있습니다.
로빈: 어디에 있습니까?
제냐: (도서관)은/는 (운동장 앞)에 있습니다. (로빈) 씨, 학교에 (서점)이/가 있습니까?
로빈: 네, (서점)은/는 (은행 아래)에 있습니다.
제냐: 감사합니다. 안녕히 가세요.
로빈: 네, 안녕히 가세요.',
  null,
  '{}'::jsonb,
  'draft',
  '1.0.0'
)
;

insert into public.reading_passages (
  id, logical_id, primary_module_id, title_ko, title_ru, body_ko, translation_ru, payload, status, content_version
) values (
  'e55c309e-1bfc-41fc-9fc0-afed3e07a60c',
  'passage.u02.section.37',
  '706d624f-aefd-42e9-a146-d7b88ae10f4d',
  '고향집을 소개하는 글을 읽고 말하기',
  '고향집을 소개하는 글을 읽고 말하기',
  '저는 로빈입니다. 제 고향집은 미국의 시카고에 있습니다. 우리 집은 이층집입니다.
( ㉠ )에는 거실, 부엌, 아래층 화장실, 부모님 방이 있습니다. 거실에 텔레비전, 소파가 있습니다. 부엌에 냉장고, 식탁이 있습니다. 부모님 방에 침대, 옷장이 있습니다.
위층에는 제 방, 위층 화장실이 있습니다. 제 방에 침대, 책상, 옷장이 있습니다. 책상 위에 책, 공책, 컴퓨터가 있습니다. 화장실은 제 방의 오른쪽에 있습니다.',
  null,
  '{}'::jsonb,
  'published',
  '1.0.0'
)
;

insert into public.reading_passages (
